{
  "steps": [
    {
      "title": "დაარეგულირე სიმაღლე",
      "text": "გამოსწიე ყვითელი ღილაკი სავარძლის ქვეშ და ისე დააყენე, რომ ჯდომისას მუხლები ბალიშების ქვეშ მჭიდროდ მოექცეს.",
      "focus": ["p6", "p5"],
      "avoid": [],
      "markers": [
        {"part": "p6", "label": "სიმაღლის რეგულირება", "tone": "brand"}
      ],
      "arrows": [],
      "tools": [],
      "warn": "სამიზნედ არჩეულია p6, რადგან ფოტოზე სავარძლის ქვეშაა; წონების ფილებთან მდებარე ყვითელი ქინძისთავი p2 სხვა ფუნქციას ასრულებს. სიმაღლე დატვირთვის გარეშე შეცვალე და დარწმუნდი, რომ სავარძელი დაფიქსირდა."
    },
    {
      "title": "აირჩიე წონა",
      "text": "ყვითელი ქინძისთავი გადაიტანე სასურველ ფილაში და ბოლომდე ჩაარჭე.",
      "focus": ["p2"],
      "avoid": [],
      "markers": [
        {"part": "p2", "label": "წონის ასარჩევი ქინძისთავი", "tone": "brand"}
      ],
      "arrows": [],
      "tools": [],
      "warn": "p2 შერჩეულია წონების ფილებთან მდებარეობის მიხედვით და არა მხოლოდ ყვითელი ფერის გამო. წონა შეცვალე მხოლოდ მაშინ, როცა ფილები უძრავია და სრულად დაშვებულია; ფოტოდან წონის მნიშვნელობა ვერ დასტურდება."
    },
    {
      "title": "მოკიდე სახელურს",
      "text": "ფეხზე მდგომმა მოკიდე ხელი მოხრილ ბოლოებთან, მხრებზე ოდნავ ფართოდ, ხელისგულები წინ.",
      "focus": ["p1"],
      "avoid": [],
      "markers": [
        {"part": "p1", "label": "მოჭიდება მოხრილ ბოლოებთან", "tone": "brand"}
      ],
      "arrows": [],
      "tools": [],
      "warn": null
    },
    {
      "title": "დაჯექი და დაფიქსირდი",
      "text": "სახელურით ხელში დაჯექი, ფეხები იატაკზე, მუხლები ბალიშების ქვეშ. მკერდი წინ, ზურგი სწორი.",
      "focus": ["p5", "p3", "p4", "p1"],
      "avoid": [],
      "markers": [
        {"part": "p5", "label": "დაჯექი", "tone": "brand"},
        {"part": "p3", "label": "მუხლი ბალიშის ქვეშ", "tone": "neutral"},
        {"part": "p4", "label": "მუხლი ბალიშის ქვეშ", "tone": "neutral"}
      ],
      "arrows": [],
      "tools": [],
      "warn": null
    },
    {
      "title": "ჩამოწიე მკერდამდე",
      "text": "იდაყვები ქვემოთ და უკან, სახელური მკერდის ზედა ნაწილამდე. ზემოთ ნელა აუშვი, 2 წამში.",
      "focus": ["p1"],
      "avoid": [],
      "markers": [
        {"part": "p1", "label": "ჩამოწევა და კონტროლირებული დაბრუნება", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p1", "type": "move", "dir": "down"},
        {"part": "p1", "type": "move", "dir": "up"}
      ],
      "tools": [],
      "warn": "არ მოქაჩო ინერციით და არ ჩამოიტანო სახელური კისრის უკან. 2 წამი ინსტრუქციით მითითებული ტემპია და არა ფოტოდან დადგენილი მონაცემი."
    }
  ],
  "unknown_parts": []
}
